//! Ownership and checked invocation of executable native code.

use std::sync::{Mutex, PoisonError};

use cranelift_jit::JITModule;

use crate::utils::errors::{QSError, Result};

/// Native function generated by Cranelift, writing a checked value and gradient layout.
pub type RawKernel = unsafe extern "C" fn(*const f64, *mut f64, *mut f64);

/// Lifetime owner for compiled executable pages.
///
/// The `JITModule` is
/// *never* accessed during evaluation; the Mutex merely makes its ownership
/// safely shareable across Rayon workers. The last Arc cannot drop while
/// another call still holds a kernel reference.
pub struct NativeKernel {
    module: Mutex<Option<JITModule>>,
    function: RawKernel,
    inputs: usize,
    outputs: usize,
    gradients: usize,
}

impl Drop for NativeKernel {
    /// Releases the JIT module and its owned executable memory.
    fn drop(&mut self) {
        let module = self
            .module
            .get_mut()
            .unwrap_or_else(PoisonError::into_inner);
        if let Some(module) = module.take() {
            // SAFETY: The final Arc is being dropped, so no evaluation can still
            // hold a kernel reference or call its private function pointer.
            unsafe { module.free_memory() };
        }
    }
}

impl NativeKernel {
    /// Owns a generated value-and-gradient function and its executable pages.
    ///
    /// # Safety
    /// `function` must belong to `module`, use the declared C ABI, read exactly
    /// `inputs` doubles, and write one value and exactly `inputs` derivatives.
    pub unsafe fn new(module: JITModule, function: RawKernel, inputs: usize) -> Self {
        // SAFETY: The scalar layout is the layout required by this constructor.
        unsafe { Self::with_layout(module, function, inputs, 1, inputs) }
    }

    /// Owns a generated multi-output function with a checked derivative layout.
    ///
    /// # Safety
    /// The live function must belong to `module`, read `inputs` doubles, write
    /// `outputs` values and `gradients` derivatives using the declared C ABI.
    pub unsafe fn with_layout(
        module: JITModule,
        function: RawKernel,
        inputs: usize,
        outputs: usize,
        gradients: usize,
    ) -> Self {
        Self {
            module: Mutex::new(Some(module)),
            function,
            inputs,
            outputs,
            gradients,
        }
    }

    /// Calls the generated code after validating both buffer lengths.
    ///
    /// # Errors
    /// Returns an input or gradient length error before entering native code.
    pub fn value_and_grad(&self, inputs: &[f64], gradients: &mut [f64]) -> Result<f64> {
        if self.outputs != 1 {
            return Err(QSError::BufferCount {
                buffer: "output",
                expected: self.outputs,
                actual: 1,
            });
        }
        let mut values = [0.0];
        self.values_and_grad(inputs, &mut values, gradients)?;
        Ok(values[0])
    }

    /// Evaluates all outputs and the compiler-defined derivative layout.
    ///
    /// # Errors
    /// Rejects every incompatible buffer before entering generated code.
    pub fn values_and_grad(
        &self,
        inputs: &[f64],
        outputs: &mut [f64],
        gradients: &mut [f64],
    ) -> Result<()> {
        if inputs.len() != self.inputs {
            return Err(QSError::InputCount {
                expected: self.inputs,
                actual: inputs.len(),
            });
        }
        if outputs.len() != self.outputs {
            return Err(QSError::BufferCount {
                buffer: "output",
                expected: self.outputs,
                actual: outputs.len(),
            });
        }
        if gradients.len() != self.gradients {
            return Err(QSError::GradientCount {
                expected: self.gradients,
                actual: gradients.len(),
            });
        }
        // SAFETY: Exact lengths were checked and self owns the live executable pages.
        unsafe {
            (self.function)(
                inputs.as_ptr(),
                outputs.as_mut_ptr(),
                gradients.as_mut_ptr(),
            );
        };
        Ok(())
    }
}
